package com.sathavahana.kalamkari.dto; import com.sathavahana.kalamkari.domain.*; import java.math.*; import java.util.*; public record CartDto(Long id,List<Item> items,BigDecimal total){public record Item(Long productId,String name,int quantity,BigDecimal unitPrice,BigDecimal lineTotal){} public static CartDto of(Cart c){var i=c.getItems().stream().map(x->new Item(x.getProduct().getId(),x.getProduct().getName(),x.getQuantity(),x.getUnitPrice(),x.getUnitPrice().multiply(BigDecimal.valueOf(x.getQuantity())))).toList(); return new CartDto(c.getId(),i,i.stream().map(Item::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add));}}
